       cs_real_3_t *vdp_i = NULL;

-      if (f_vdp_i != NULL)
+      if (f_vdp_i != NULL) {
         vdp_i = (cs_real_3_t *)f_vdp_i->val;

-      for (cs_lnum_t c_id = 0; c_id < n_cells; c_id++) {
+        for (cs_lnum_t c_id = 0; c_id < n_cells; c_id++) {

